import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import UserManagement from './pages/UserManagement';
import DriverManagement from './pages/DriverManagement';
import CabManagement from './pages/CabManagement';
import LocationManagement from './pages/LocationManagement';
import Layout from './components/Layout';
import ProtectedRoute from './components/ProtectedRoute';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Layout />
            </ProtectedRoute>
          }
        >
          <Route index element={<Navigate to="/dashboard" replace />} />
          <Route
            path="dashboard"
            element={<ProtectedRoute><Dashboard /></ProtectedRoute>}
          />
          <Route
            path="users"
            element={<ProtectedRoute><UserManagement /></ProtectedRoute>}
          />
          <Route
            path="drivers"
            element={<ProtectedRoute><DriverManagement /></ProtectedRoute>}
          />
          <Route
            path="cabs"
            element={<ProtectedRoute><CabManagement /></ProtectedRoute>}
          />
          <Route
            path="locations"
            element={<ProtectedRoute><LocationManagement /></ProtectedRoute>}
          />
        </Route>
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
